Action.ExecScriptExpression:
using System;
using Triggernometry;
using Triggernometry.Core;
using Triggernometry.Core.Variables;

VariableStore store = RealPlugin.Instance.GetVariableStore(false);

var allBossSkillDict = store.Dict["The_Forked_Tower_Magic_allBossSkillDict"] as VariableDictionary;
if (allBossSkillDict == null) return;

string targetId = "${targetId}";
string playerName = "${target}";
string samuraiKey = $"{targetId}_{playerName}";

for (int i = 1; i <= 3; i++)
{
    var bossDict = allBossSkillDict.GetValue($"boss{i}") as VariableDictionary;
    if (bossDict == null) continue;
    
    var throwMoneyDict = bossDict.GetValue("扔钱") as VariableDictionary;
    var iaijutsuDict = bossDict.GetValue("居合") as VariableDictionary;
    
    throwMoneyDict?.SetValue(samuraiKey, "0");
    iaijutsuDict?.SetValue(samuraiKey, "0");
}

allBossSkillDict.LastChanger = "Mata";
allBossSkillDict.LastChanged = DateTime.Now;

store.Dict["The_Forked_Tower_Magic_allBossSkillDict"] = allBossSkillDict;

using System;
using Triggernometry;
using Triggernometry.Core;
using Triggernometry.Core.Variables;

var allBossSkillDict = new VariableDictionary();
for (int i = 1; i <= 3; i++)
{
    var bossDict = new VariableDictionary();
    bossDict.SetValue("扔钱", new VariableDictionary());
    bossDict.SetValue("居合", new VariableDictionary());
    allBossSkillDict.SetValue($"boss{i}", bossDict);
}

allBossSkillDict.LastChanger = "Mata";
allBossSkillDict.LastChanged = DateTime.Now;

VariableStore globalVarStore = RealPlugin.Instance.GetVariableStore(false);
globalVarStore.Dict["The_Forked_Tower_Magic_allBossSkillDict"] = allBossSkillDict;

using System;
using Triggernometry;
using Triggernometry.Core;
using Triggernometry.Core.Variables;

VariableStore store = RealPlugin.Instance.GetVariableStore(false);

var allBossSkillDict = store.Dict["The_Forked_Tower_Magic_allBossSkillDict"] as VariableDictionary;
if (allBossSkillDict == null) return;

string sourceId = "${sourceId}";
string playerName = "${source}";
string skillId = "${id}";
string target = "${target}";

string bossNum = target switch
{
    "绿头" => "boss1",
    "蓝头" => "boss1",
    "剑舞者" => "boss2",
    "惧死者" => "boss3",
    _ => ""
};

if (string.IsNullOrEmpty(bossNum)) return;

string skillName = skillId == "A285" ? "居合" : "扔钱";
string key = $"{sourceId}_{playerName}";

var bossDict = allBossSkillDict.GetValue(bossNum) as VariableDictionary;
if (bossDict == null) return;

var skillDict = bossDict.GetValue(skillName) as VariableDictionary;
if (skillDict == null) return;

string currentVal = skillDict.GetValue(key)?.ToString() ?? "0";
int count = int.TryParse(currentVal, out int c) ? c : 0;
skillDict.SetValue(key, (count + 1).ToString());

allBossSkillDict.LastChanger = "Mata";
allBossSkillDict.LastChanged = DateTime.Now;

store.Dict["The_Forked_Tower_Magic_allBossSkillDict"] = allBossSkillDict;

using System;
using System.Linq;
using System.Text;
using Triggernometry;
using Triggernometry.Core;
using Triggernometry.Core.Variables;
using Triggernometry.Utilities;
using Triggernometry.FFXIV;

// 日志输出函数
static void Log(string msg) => RealPlugin.plug.InvokeNamedCallback("command", "/e " + msg);

// 使用StringBuilder优化字符串拼接性能
var output = new StringBuilder();
var allEntities = Triggernometry.FFXIV.Entity.GetEntities().Where(e => e.BNpcID == 0);

// 读取食物buff（状态ID=48）剩余时间，小于300秒告警
foreach (var entity in allEntities)
{
    // 空值防护：避免实体为空导致的异常
    if (entity == null || entity.Statuses == null) continue;
    
    Status foodStatus = entity.Statuses.FirstOrDefault(s => s.StatusID == 48);
    if (foodStatus != null)
    {
        // 剩余时间小于300秒（5分钟）时记录
        if (foodStatus.Timer < 300)
        {
            output.Append(entity.Name).Append("(").Append((int)foodStatus.Timer).Append("秒),");
        }
    }
    else
    {
        // 无食物buff时显示0秒
        output.Append(entity.Name).Append("(0秒),");
    }
}

// 处理输出结果
string result;
if (output.Length == 0)
{
    result = "所有人都吃饭了";
}
else
{
    // 移除末尾的逗号
    result = "食物时间不够的是：" + output.ToString(0, output.Length - 1);
}

Log(result);

using System;
using System.Text;
using System.Linq;
using System.Collections.Generic;
using Triggernometry;
using Triggernometry.Core;
using Triggernometry.Core.Variables;

VariableStore store = RealPlugin.Instance.GetVariableStore(false);

var allBossSkillDict = store.Dict["The_Forked_Tower_Magic_allBossSkillDict"] as VariableDictionary;
if (allBossSkillDict == null) return;

string zoneId = "${zoneid}";

string bossNum = zoneId switch
{
    "1573" => "boss1",
    "1574" => "boss2",
    "1575" => "boss3",
    _ => ""
};

if (string.IsNullOrEmpty(bossNum)) return;

string time1Str = "${v:The_Forked_Tower_Magic_" + zoneId + "_time1}";
string time2Str = "${v:The_Forked_Tower_Magic_" + zoneId + "_time2}";
if (!int.TryParse(time1Str, out int time1)) return;
if (!int.TryParse(time2Str, out int time2)) return;

if (bossNum == "boss1")
    time2++;

var bossDict = allBossSkillDict.GetValue(bossNum) as VariableDictionary;
if (bossDict == null) return;

var throwMoneyDict = bossDict.GetValue("扔钱") as VariableDictionary;
var iaijutsuDict = bossDict.GetValue("居合") as VariableDictionary;

var failedDict = new Dictionary<string, List<string>>();

if (throwMoneyDict != null)
{
    foreach (var item in throwMoneyDict.Values)
    {
        string playerKey = item.Key;
        int nameStart = playerKey.IndexOf('_') + 1;
        if (nameStart <= 0 || nameStart >= playerKey.Length) continue;
        string name = playerKey.Substring(nameStart);
        
        int count = int.TryParse(item.Value?.ToString(), out int c) ? c : 0;
        if (count < time1)
        {
            if (!failedDict.ContainsKey(name))
                failedDict[name] = new List<string>();
            failedDict[name].Add($"扔钱{count}/{time1}");
        }
    }
}

if (iaijutsuDict != null)
{
    foreach (var item in iaijutsuDict.Values)
    {
        string playerKey = item.Key;
        int nameStart = playerKey.IndexOf('_') + 1;
        if (nameStart <= 0 || nameStart >= playerKey.Length) continue;
        string name = playerKey.Substring(nameStart);
        
        int count = int.TryParse(item.Value?.ToString(), out int c) ? c : 0;
        if (count < time2)
        {
            if (!failedDict.ContainsKey(name))
                failedDict[name] = new List<string>();
            failedDict[name].Add($"居合{count}/{time2}");
        }
    }
}

string result;
if (failedDict.Any())
{
    var parts = new List<string>();
    foreach (var kv in failedDict)
    {
        parts.Add($"{kv.Key}({string.Join("，", kv.Value)})");
    }
    result = "辅助武士技能不合格：" + string.Join("，", parts);
}
else
{
    result = "辅助武士技能合格";
}

RealPlugin.plug.InvokeNamedCallback("command", $"/e {result}");

